INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('bb058649-ab7c-4216-9203-7cb95d316bc4', '150f78d3-019b-40c0-962e-a83576309ea5', 7, 'A Morada do Amado', NULL, '{"intro": "Toda busca humana \u00e9, no fundo, uma busca pelo Lar.", "prayer": "Descanse na presen\u00e7a dEle dentro de voc\u00ea.", "practice": "Sinta o seu cora\u00e7\u00e3o como um templo sagrado.", "reflection": "O cora\u00e7\u00e3o \u00e9 um abismo que s\u00f3 o Infinito pode preencher.", "journal_prompt": "Voc\u00ea j\u00e1 se sentiu em casa?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('39102329-9633-4eea-8b4e-3e3da8ec8815', '9f444a3e-9838-48b8-ae77-0b5a6829d4fa', 1, 'A Rocha e a Areia', NULL, '{"intro": "Fundamentos invis\u00edveis sustentam estruturas vis\u00edveis.", "prayer": "Pe\u00e7a para construir sua vida sobre o que \u00e9 eterno.", "practice": "Analise em que base sua seguran\u00e7a hoje se apoia.", "reflection": "Onde voc\u00ea est\u00e1 construindo a sua casa?", "journal_prompt": "Se tudo desabasse, o que sobraria de voc\u00ea?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('8399a510-c51a-426e-ac6a-386a50ce893e', '9f444a3e-9838-48b8-ae77-0b5a6829d4fa', 2, 'A Revelação do Sentido', NULL, '{"intro": "A busca por sentido \u00e9 a necessidade mais profunda da alma.", "prayer": "Contemple a cria\u00e7\u00e3o e veja nela um recado para voc\u00ea.", "practice": "Observe a beleza de algo simples ao seu redor.", "reflection": "A vida n\u00e3o \u00e9 um acaso, \u00e9 um chamado.", "journal_prompt": "O que a vida est\u00e1 pedindo de voc\u00ea agora?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('455223dc-ebfb-4b93-99f2-c5835037f4e4', '9f444a3e-9838-48b8-ae77-0b5a6829d4fa', 3, 'O Mistério da Encarnação', NULL, '{"intro": "A realidade material \u00e9 sagrada e cheia de presen\u00e7a.", "prayer": "Agrade\u00e7a pela sua humanidade limitada.", "practice": "Toque a terra, sinta o seu corpo, habite o presente.", "reflection": "Deus se fez carne para que a carne se tornasse divina.", "journal_prompt": "Voc\u00ea aceita as limita\u00e7\u00f5es da sua pr\u00f3pria carne?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('6ed33434-274a-4020-bca3-3a10bf234d08', '9f444a3e-9838-48b8-ae77-0b5a6829d4fa', 4, 'A Lei do Amor', NULL, '{"intro": "A lei sem amor \u00e9 escravid\u00e3o; o amor sem lei \u00e9 caos.", "prayer": "Pe\u00e7a para ver o outro como Ele o v\u00ea.", "practice": "Aja hoje motivado apenas pelo amor, n\u00e3o pelo dever.", "reflection": "N\u00e3o existem regras, existe uma Pessoa a quem amamos.", "journal_prompt": "O que move as suas a\u00e7\u00f5es: o medo ou o amor?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('859fc2d1-0d9f-4e12-a9ab-6f16e22a36a1', '9f444a3e-9838-48b8-ae77-0b5a6829d4fa', 5, 'A Comunhão dos Santos', NULL, '{"intro": "A solid\u00e3o \u00e9 um mito; estamos todos interconectados.", "prayer": "Sinta a companhia daqueles que j\u00e1 venceram.", "practice": "Lembre-se de algu\u00e9m que te inspira e siga seu exemplo.", "reflection": "Ningu\u00e9m caminha sozinho para o alto.", "journal_prompt": "Quem caminha com voc\u00ea no seu cora\u00e7\u00e3o?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('e9f5a167-6858-4495-b2b1-c9c96c462582', '9f444a3e-9838-48b8-ae77-0b5a6829d4fa', 6, 'A Cruz como Portal', NULL, '{"intro": "A aceita\u00e7\u00e3o da dor \u00e9 a chave para a verdadeira paz.", "prayer": "Ofere\u00e7a sua dor como um gesto de amor.", "practice": "N\u00e3o reclame de um pequeno desconforto hoje.", "reflection": "O sofrimento n\u00e3o \u00e9 um beco sem sa\u00edda, \u00e9 uma passagem.", "journal_prompt": "O que voc\u00ea est\u00e1 tentando evitar a qualquer custo?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('9812a6fd-f7c5-4b3b-b44e-97aa508d327e', '9f444a3e-9838-48b8-ae77-0b5a6829d4fa', 7, 'A Esperança da Glória', NULL, '{"intro": "A esperan\u00e7a nos permite viver o futuro no presente.", "prayer": "Descanse na promessa de que tudo ficar\u00e1 bem.", "practice": "Olhe para o horizonte e sorria para o amanh\u00e3.", "reflection": "O fim da jornada \u00e9 apenas o verdadeiro come\u00e7o.", "journal_prompt": "Pelo que voc\u00ea est\u00e1 esperando?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('998b1157-ad77-4a35-a53b-7b6cb6fa67fc', 'a1a1a1a1-3030-4000-8000-000000000001', 1, 'Dia 1 — Inquietação', 'Semana 1: Despertar', '{"pch": "Antes de te formar no ventre\u2026 Eu j\u00e1 te conhecia. Voc\u00ea n\u00e3o \u00e9 acidente \u2014 \u00e9 projeto.", "verse": "Jr 1,5", "lectio": "Leia Jr 1,4-10 lentamente. Perceba que Deus fala antes de voc\u00ea agir.", "practice": "Escreva 3 coisas que te fazem sentir vivo.", "question": "O que te inquieta quando pensa no futuro?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('4c0d4e4c-d023-49e8-9015-bab9638bd850', 'a1a1a1a1-3030-4000-8000-000000000001', 2, 'Dia 2 — Escuta', 'Semana 1: Despertar', '{"pch": "Fala, Senhor\u2026 seu servo escuta. E se a voz que voc\u00ea ignora fosse a mais importante?", "verse": "1Sm 3,10", "lectio": "Leia 1Sm 3,1-10. Samuel precisou aprender a reconhecer a voz.", "practice": "Fique 5 minutos em sil\u00eancio absoluto. Anote o que surgir.", "question": "Quando foi a \u00faltima vez que voc\u00ea parou para ouvir?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('5138f2ed-b82a-4c75-a2e9-c5c674905476', 'a1a1a1a1-3030-4000-8000-000000000001', 3, 'Dia 3 — Identidade', 'Semana 1: Despertar', '{"pch": "Voc\u00ea foi tecido em segredo\u2026 mas n\u00e3o por acaso. Cada detalhe seu \u00e9 intencional.", "verse": "Sl 139,13-14", "lectio": "Leia Sl 139,13-18. Deus te conhece por dentro.", "practice": "Liste 3 qualidades suas que outros j\u00e1 elogiaram.", "question": "O que voc\u00ea gosta em si mesmo que nunca valorizou?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('c8b91851-b773-4634-b175-606f16a1bdd4', 'a1a1a1a1-3030-4000-8000-000000000001', 4, 'Dia 4 — Dons', 'Semana 1: Despertar', '{"pch": "A cada um \u00e9 dada uma manifesta\u00e7\u00e3o do Esp\u00edrito\u2026 para o bem de todos. Seus dons n\u00e3o s\u00e3o para voc\u00ea.", "verse": "1Cor 12,7", "lectio": "Leia 1Cor 12,4-11. Cada dom \u00e9 \u00fanico e necess\u00e1rio.", "practice": "Pergunte a 2 pessoas pr\u00f3ximas: qual meu maior talento?", "question": "O que voc\u00ea faz com facilidade que outros acham dif\u00edcil?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('68da5888-cdf5-4fff-a61b-c6564471e6b6', 'a1a1a1a1-3030-4000-8000-000000000001', 5, 'Dia 5 — Sonhos', 'Semana 1: Despertar', '{"pch": "Ele pode fazer infinitamente mais\u2026 do que pedimos ou imaginamos. Seus sonhos s\u00e3o pequenos demais.", "verse": "Ef 3,20", "lectio": "Leia Ef 3,14-21. A ora\u00e7\u00e3o de Paulo \u00e9 um convite \u00e0 grandeza.", "practice": "Escreva seu maior sonho sem censura.", "question": "Se n\u00e3o houvesse limites, o que voc\u00ea faria?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('2c6ea5f0-16c1-4157-9983-0e671662dc7d', 'a1a1a1a1-3030-4000-8000-000000000001', 6, 'Dia 6 — Medo', 'Semana 1: Despertar', '{"pch": "N\u00e3o temas, pois estou contigo\u2026 O medo \u00e9 real, mas n\u00e3o \u00e9 verdadeiro.", "verse": "Is 41,10", "lectio": "Leia Is 41,8-13. Deus segura sua m\u00e3o direita.", "practice": "Nomeie seu maior medo. Depois, entregue-o em ora\u00e7\u00e3o.", "question": "Qual medo te impede de avan\u00e7ar?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('4fe490ab-b93c-4111-903e-f6594093c2ec', 'a1a1a1a1-3030-4000-8000-000000000001', 7, 'Dia 7 — Entrega', 'Semana 1: Despertar', '{"pch": "Confia ao Senhor as tuas obras\u2026 e os teus planos ser\u00e3o estabelecidos. Solte o controle.", "verse": "Pv 16,3", "lectio": "Leia Pv 16,1-9. O cora\u00e7\u00e3o planeja, mas Deus dirige.", "practice": "Fa\u00e7a uma ora\u00e7\u00e3o de entrega: Senhor, minha vida \u00e9 tua.", "question": "O que voc\u00ea precisa entregar a Deus hoje?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('bb057ba9-b3be-4549-b096-7d10af160978', 'a1a1a1a1-3030-4000-8000-000000000001', 8, 'Dia 8 — Raízes', 'Semana 2: Desconstruir', '{"pch": "Toda \u00e1rvore boa d\u00e1 bons frutos\u2026 Antes de mudar os frutos, examine as ra\u00edzes.", "verse": "Mt 7,17", "lectio": "Leia Mt 7,15-20. Os frutos revelam a raiz.", "practice": "Escreva 3 cren\u00e7as negativas que carrega desde a inf\u00e2ncia.", "question": "Que cren\u00e7as sobre voc\u00ea mesmo te limitam?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('d43f46b7-ab47-4b02-9524-be185e2f09b4', 'a1a1a1a1-3030-4000-8000-000000000001', 9, 'Dia 9 — Comparação', 'Semana 2: Desconstruir', '{"pch": "Cada um examine a pr\u00f3pria obra\u2026 sem se comparar. Sua corrida \u00e9 s\u00f3 sua.", "verse": "Gl 6,4", "lectio": "Leia Gl 6,1-5. Cada um carregar\u00e1 seu pr\u00f3prio fardo.", "practice": "Desative as redes sociais por 24h. Observe como se sente.", "question": "Com quem voc\u00ea se compara? E por qu\u00ea?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('5d957e20-f7a8-4aac-b2ce-962d35426dba', 'a1a1a1a1-3030-4000-8000-000000000001', 10, 'Dia 10 — Expectativas', 'Semana 2: Desconstruir', '{"pch": "N\u00e3o se conformem\u2026 Transformem-se. As expectativas dos outros n\u00e3o s\u00e3o o plano de Deus para voc\u00ea.", "verse": "Rm 12,2", "lectio": "Leia Rm 12,1-8. Renovar a mente \u00e9 o caminho.", "practice": "Escreva: o que EU quero vs. o que ESPERAM de mim.", "question": "Que expectativa alheia voc\u00ea carrega como sua?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('d805edc0-7835-436f-8dca-41e06e9b3b45', 'a1a1a1a1-3030-4000-8000-000000000001', 11, 'Dia 11 — Feridas', 'Semana 2: Desconstruir', '{"pch": "Minha gra\u00e7a te basta\u2026 A for\u00e7a se aperfei\u00e7oa na fraqueza. Suas feridas t\u00eam prop\u00f3sito.", "verse": "2Cor 12,9", "lectio": "Leia 2Cor 12,7-10. Paulo encontrou for\u00e7a na fraqueza.", "practice": "Escreva uma carta de perd\u00e3o a si mesmo.", "question": "Que dor do passado ainda influencia suas decis\u00f5es?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('eb92ec35-11e0-4f15-adeb-e8b806751a75', 'a1a1a1a1-3030-4000-8000-000000000001', 12, 'Dia 12 — Desapego', 'Semana 2: Desconstruir', '{"pch": "Esquecendo-me do que fica para tr\u00e1s\u2026 avan\u00e7ando para o que est\u00e1 adiante. Solte o passado.", "verse": "Fl 3,13", "lectio": "Leia Fl 3,12-16. Paulo corria para frente.", "practice": "Escolha algo simb\u00f3lico para soltar hoje \u2014 um objeto, uma mem\u00f3ria, um ressentimento.", "question": "O que do passado voc\u00ea precisa largar para avan\u00e7ar?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
